import numpy as np
from sklearn.ensemble import HistGradientBoostingRegressor

def _make(seed):
    return HistGradientBoostingRegressor(max_iter=250, learning_rate=0.08, max_leaf_nodes=31, l2_regularization=1.0, early_stopping=False, random_state=int(seed) % 2147483647)

def _f(name, v):
    if name == 'log1p':
        return np.log1p(np.maximum(v, 0.0))
    if name == 'sqrt':
        return np.sqrt(np.maximum(v, 0.0))
    return v

def _finv(name, v):
    if name == 'log1p':
        return np.expm1(np.minimum(v, 12.0))
    if name == 'sqrt':
        return np.square(np.maximum(v, 0.0))
    return v

def fit_predict(train, inputs, seed):
    X = np.asarray(train['X'], dtype=float)
    y = np.asarray(train['y'], dtype=float)
    Xe = np.asarray(inputs['X'], dtype=float)
    names = list(train['feature_names'])
    findings = {'fallback_used': False, 'early_stopping': False}
    ed = names.index('elapsed_day')
    day = X[:, ed]
    udays = np.unique(day)
    ncut = 61 if len(udays) > 122 else max(1, len(udays) // 4)
    cut = udays[-ncut]
    tr = day < cut
    ho = ~tr
    findings['internal_holdout'] = {'days': int(ncut), 'rows': int(ho.sum()), 'cut_elapsed_day': float(cut), 'train_rows': int(tr.sum())}
    fsets = {'all': list(range(X.shape[1])), 'no_elapsed_day': [i for i in range(X.shape[1]) if i != ed]}
    results = {}
    for t in ['raw', 'log1p', 'sqrt']:
        for fs, cols in fsets.items():
            m = _make(seed)
            m.fit(X[tr][:, cols], _f(t, y[tr]))
            p = np.clip(_finv(t, m.predict(X[ho][:, cols])), 0.0, None)
            e = p - y[ho]
            results[t + '|' + fs] = {'rmse': float(np.sqrt(np.mean(e ** 2))), 'mae': float(np.mean(np.abs(e))), 'bias': float(np.mean(e))}
    best = min(results, key=lambda k: results[k]['rmse'])
    t, fs = best.split('|')
    cols = fsets[fs]
    findings['internal_results'] = results
    findings['selected'] = {'transform': t, 'features': fs}
    try:
        yi = names.index('yr')
        mi = names.index('mnth')
        lv = {}
        for mo in np.unique(X[:, mi]):
            a = y[(X[:, mi] == mo) & (X[:, yi] == 0)]
            b = y[(X[:, mi] == mo) & (X[:, yi] == 1)]
            if len(a) and len(b):
                lv[str(int(mo))] = {'mean_2011': float(a.mean()), 'mean_2012': float(b.mean()), 'ratio': float(b.mean() / max(a.mean(), 1e-9))}
        findings['year_level_by_month'] = lv
    except Exception as exc:
        findings['level_diag_error'] = type(exc).__name__
    m = _make(seed)
    m.fit(X[:, cols], _f(t, y))
    pred = np.clip(_finv(t, m.predict(Xe[:, cols])), 0.0, None)
    bad = ~np.isfinite(pred)
    if bad.any():
        findings['fallback_used'] = True
        findings['nonfinite_replaced'] = int(bad.sum())
        pred[bad] = float(np.median(y))
    findings['pred_mean'] = float(pred.mean())
    findings['train_mean'] = float(y.mean())
    return {'prediction': pred.tolist(), 'findings': findings}

import numpy as np
from sklearn.ensemble import HistGradientBoostingRegressor

def _hgb(seed):
    return HistGradientBoostingRegressor(max_iter=250, learning_rate=0.08, max_leaf_nodes=31, l2_regularization=1.0, early_stopping=False, random_state=int(seed) % 2147483647)

def _daily_level(X, y, day, cols, seed, nblocks=5):
    ud = np.unique(day)
    ly = np.log1p(np.maximum(y, 0.0))
    res = np.zeros(len(y))
    for b in np.array_split(ud, nblocks):
        m = np.isin(day, b)
        if m.sum() == 0 or (~m).sum() == 0:
            continue
        mdl = _hgb(seed)
        mdl.fit(X[~m][:, cols], ly[~m])
        res[m] = ly[m] - mdl.predict(X[m][:, cols])
    rr = np.array([res[day == d].mean() for d in ud])
    return ud, rr

def _offset(dd, rr, mode, eday):
    if mode == 'none':
        return np.zeros(len(eday)), {}
    if mode == 'const60':
        w = dd >= dd[-1] - 59
        c = float(rr[w].mean())
        return np.full(len(eday), c), {'const': c, 'n_days': int(w.sum())}
    if mode == 'trend_all':
        a, b = np.polyfit(dd, rr, 1)
        return a * eday + b, {'slope_per_day': float(a), 'intercept': float(b), 'n_days': int(len(dd))}
    if mode == 'trend180':
        w = dd >= dd[-1] - 179
        a, b = np.polyfit(dd[w], rr[w], 1)
        return a * eday + b, {'slope_per_day': float(a), 'intercept': float(b), 'n_days': int(w.sum())}
    raise ValueError(mode)

def _predict_level(X, y, day, Xe, eday, cols, mode, seed):
    ly = np.log1p(np.maximum(y, 0.0))
    dd, rr = _daily_level(X, y, day, cols, seed)
    off, info = _offset(dd, rr, mode, eday)
    mdl = _hgb(seed)
    mdl.fit(X[:, cols], ly)
    lp = mdl.predict(Xe[:, cols]) + off
    p = np.expm1(np.minimum(lp, 12.0))
    info['mean_offset'] = float(np.mean(off))
    return np.clip(p, 0.0, None), info

def _predict_base(X, y, Xe, seed):
    mdl = _hgb(seed)
    mdl.fit(X, y)
    return np.clip(mdl.predict(Xe), 0.0, None)

def _metrics(p, y):
    e = p - y
    return {'rmse': float(np.sqrt(np.mean(e ** 2))), 'mae': float(np.mean(np.abs(e))), 'bias': float(np.mean(e))}

def fit_predict(train, inputs, seed):
    X = np.asarray(train['X'], dtype=float)
    y = np.asarray(train['y'], dtype=float)
    Xe = np.asarray(inputs['X'], dtype=float)
    names = list(train['feature_names'])
    ed = names.index('elapsed_day')
    yi = names.index('yr')
    cols = [i for i in range(X.shape[1]) if i not in (ed, yi)]
    day = X[:, ed]
    eday = Xe[:, ed]
    findings = {'fallback_used': False, 'shape_features_exclude': ['elapsed_day', 'yr'], 'level_model': 'cross_fitted_daily_mean_log1p_residual_5_date_blocks', 'target_for_level_variants': 'log1p'}
    ud = np.unique(day)
    modes = ['none', 'const60', 'trend_all', 'trend180']
    folds = [(ud[-60], ud[-30]), (ud[-30], ud[-1] + 1.0)]
    internal = {}
    for fi, (lo, hi) in enumerate(folds):
        tr = day < lo
        ho = (day >= lo) & (day < hi)
        fold_res = {}
        pb = _predict_base(X[tr], y[tr], X[ho], seed)
        fold_res['baseline_all_raw'] = _metrics(pb, y[ho])
        for mode in modes:
            p, info = _predict_level(X[tr], y[tr], day[tr], X[ho], day[ho], cols, mode, seed)
            r = _metrics(p, y[ho])
            r.update(info)
            fold_res['level_' + mode] = r
        internal['fold%d' % fi] = {'cut_lo': float(lo), 'cut_hi': float(hi), 'holdout_rows': int(ho.sum()), 'train_rows': int(tr.sum()), 'holdout_mean_y': float(y[ho].mean()), 'results': fold_res}
    cands = ['baseline_all_raw'] + ['level_' + m for m in modes]
    avg = {c: float(np.mean([internal[f]['results'][c]['rmse'] for f in internal])) for c in cands}
    best = min(avg, key=avg.get)
    findings['internal'] = internal
    findings['avg_internal_rmse'] = avg
    findings['selected'] = best
    try:
        dd, rr = _daily_level(X, y, day, cols, seed)
        a, b = np.polyfit(dd, rr, 1)
        w60 = dd >= dd[-1] - 59
        f60 = dd <= dd[0] + 59
        findings['full_train_level'] = {'slope_per_day_all': float(a), 'mean_first60': float(rr[f60].mean()), 'mean_last60': float(rr[w60].mean()), 'std_daily': float(rr.std())}
    except Exception as exc:
        findings['level_diag_error'] = type(exc).__name__
    if best == 'baseline_all_raw':
        pred = _predict_base(X, y, Xe, seed)
        findings['final_level_info'] = {}
    else:
        mode = best[len('level_'):]
        pred, info = _predict_level(X, y, day, Xe, eday, cols, mode, seed)
        findings['final_level_info'] = info
    pred = np.asarray(pred, dtype=float)
    bad = ~np.isfinite(pred)
    if bad.any():
        findings['fallback_used'] = True
        findings['nonfinite_replaced'] = int(bad.sum())
        pred[bad] = float(np.median(y))
    findings['pred_mean'] = float(pred.mean())
    findings['train_mean'] = float(y.mean())
    findings['train_last60_mean'] = float(y[day >= ud[-1] - 59].mean())
    findings['eval_day_range'] = [float(eday.min()), float(eday.max())]
    findings['train_day_range'] = [float(day.min()), float(day.max())]
    return {'prediction': pred.tolist(), 'findings': findings}

import numpy as np
from sklearn.ensemble import HistGradientBoostingRegressor

def _model(loss):
    return HistGradientBoostingRegressor(loss=loss, max_iter=250, learning_rate=0.08, max_leaf_nodes=31, l2_regularization=1, random_state=1729)

def _metrics(p, y):
    e = p - y
    return {'rmse': float(np.sqrt(np.mean(e ** 2))), 'mae': float(np.mean(np.abs(e))), 'bias': float(np.mean(e)), 'pred_mean': float(np.mean(p))}

def fit_predict(train, inputs, seed):
    X = np.asarray(train['X'], dtype=float)
    y = np.asarray(train['y'], dtype=float)
    Xe = np.asarray(inputs['X'], dtype=float)
    names = list(train['feature_names'])
    ed = names.index('elapsed_day')
    day = X[:, ed]
    ud = np.unique(day)
    findings = {'fallback_used': False, 'submitted': 'poisson_all_features', 'design': 'fixed submission; internal chronological folds are diagnostics only, not used for selection', 'shared_hparams': 'max_iter=250,lr=0.08,max_leaf_nodes=31,l2=1,random_state=1729,early_stopping=auto'}
    cands = {'squared_all': ('squared_error', None), 'poisson_all': ('poisson', None), 'poisson_no_elapsed': ('poisson', ed)}
    internal = {}
    for lo in [ud[-90], ud[-60], ud[-30]]:
        hi = lo + 30.0
        tr = day < lo
        ho = (day >= lo) & (day < hi)
        res = {}
        for name, (loss, drop) in cands.items():
            cols = [i for i in range(X.shape[1]) if i != drop]
            try:
                m = _model(loss)
                m.fit(X[tr][:, cols], y[tr])
                p = np.clip(m.predict(X[ho][:, cols]), 0.0, None)
                r = _metrics(p, y[ho])
                r['n_iter'] = int(m.n_iter_)
            except Exception as exc:
                r = {'error': type(exc).__name__}
            res[name] = r
        internal['cut_%d' % int(lo)] = {'train_rows': int(tr.sum()), 'holdout_rows': int(ho.sum()), 'holdout_mean_y': float(y[ho].mean()), 'results': res}
    findings['internal'] = internal
    summary = {}
    for name in cands:
        vals = [internal[k]['results'][name] for k in internal if 'rmse' in internal[k]['results'][name]]
        if vals:
            summary[name] = {'mean_rmse': float(np.mean([v['rmse'] for v in vals])), 'mean_bias': float(np.mean([v['bias'] for v in vals])), 'n_folds': len(vals)}
    findings['internal_summary'] = summary
    m11 = (day >= 0) & (day <= 120)
    m12 = (day >= 365) & (day <= 485)
    if m11.sum() > 0 and m12.sum() > 0:
        findings['jan_apr_level_ratio_2012_over_2011'] = float(y[m12].mean() / max(y[m11].mean(), 1e-9))
    try:
        m = _model('poisson')
        m.fit(X, y)
        pred = np.clip(m.predict(Xe), 0.0, None)
        findings['final_n_iter'] = int(m.n_iter_)
    except Exception as exc:
        findings['fallback_used'] = True
        findings['fallback_reason'] = type(exc).__name__
        findings['submitted'] = 'squared_error_fallback'
        m = _model('squared_error')
        m.fit(X, y)
        pred = np.clip(m.predict(Xe), 0.0, None)
    pred = np.asarray(pred, dtype=float)
    bad = ~np.isfinite(pred)
    if bad.any():
        findings['fallback_used'] = True
        findings['nonfinite_replaced'] = int(bad.sum())
        pred[bad] = float(np.median(y))
    findings['pred_mean'] = float(pred.mean())
    findings['train_mean'] = float(y.mean())
    findings['train_last60_mean'] = float(y[day >= ud[-1] - 59].mean())
    findings['eval_day_range'] = [float(Xe[:, ed].min()), float(Xe[:, ed].max())]
    return {'prediction': pred.tolist(), 'findings': findings}

import numpy as np
from sklearn.ensemble import HistGradientBoostingRegressor

def _model():
    return HistGradientBoostingRegressor(loss='poisson', max_iter=250, learning_rate=0.08, max_leaf_nodes=31, l2_regularization=1, random_state=1729)

def _metrics(p, y):
    e = p - y
    return {'rmse': float(np.sqrt(np.mean(e ** 2))), 'mae': float(np.mean(np.abs(e))), 'bias': float(np.mean(e)), 'pred_mean': float(np.mean(p))}

def _growth_rate(day, y):
    ud, inv = np.unique(day, return_inverse=True)
    tot = np.bincount(inv, weights=y)
    cnt = np.bincount(inv).astype(float)
    mean_h = tot / np.maximum(cnt, 1.0)
    idx = {float(d): i for i, d in enumerate(ud)}
    logs = []
    for i, d in enumerate(ud):
        j = idx.get(float(d) - 365.0)
        if j is None or cnt[i] < 20 or cnt[j] < 20 or mean_h[i] <= 0 or mean_h[j] <= 0:
            continue
        logs.append(float(np.log(mean_h[i] / mean_h[j])))
    if len(logs) < 20:
        return None, len(logs)
    return float(np.median(logs)) / 365.0, len(logs)

def _fit_predict(Xtr, ytr, Xte, ed, b, ref_day):
    ltr = np.exp(b * (Xtr[:, ed] - ref_day))
    lte = np.exp(b * (Xte[:, ed] - ref_day))
    m = _model()
    m.fit(Xtr, ytr / ltr)
    p = np.clip(m.predict(Xte), 0.0, None) * lte
    return p, int(m.n_iter_)

def fit_predict(train, inputs, seed):
    X = np.asarray(train['X'], dtype=float)
    y = np.asarray(train['y'], dtype=float)
    Xe = np.asarray(inputs['X'], dtype=float)
    names = list(train['feature_names'])
    ed = names.index('elapsed_day')
    day = X[:, ed]
    ud = np.unique(day)
    damps = [0.0, 0.5, 1.0]
    findings = {'fallback_used': False, 'design': 'poisson HGB (parent hparams, all features) fitted on y/L(day), L=exp(damp*b*(day-last_fit_day)); b = median log year-over-year ratio of daily mean hourly cnt / 365, estimated from the fitting window only; damp selected by mean RMSE over 3 chronological folds with 61-day horizon', 'horizon_days': 61, 'damps': damps}
    internal = {}
    for lo in [ud[-91], ud[-61], ud[-31]]:
        hi = lo + 61.0
        tr = day < lo
        ho = (day >= lo) & (day < hi)
        b, npairs = _growth_rate(day[tr], y[tr])
        fold = {'train_rows': int(tr.sum()), 'holdout_rows': int(ho.sum()), 'holdout_mean_y': float(y[ho].mean()), 'yoy_pairs': int(npairs), 'b_per_day': b, 'results': {}}
        for dmp in damps:
            key = 'damp_%.1f' % dmp
            if b is None and dmp > 0:
                fold['results'][key] = {'error': 'no_growth_estimate'}
                continue
            try:
                p, nit = _fit_predict(X[tr], y[tr], X[ho], ed, (b or 0.0) * dmp, float(day[tr].max()))
                r = _metrics(p, y[ho])
                r['n_iter'] = nit
            except Exception as exc:
                r = {'error': type(exc).__name__}
            fold['results'][key] = r
        internal['cut_%d' % int(lo)] = fold
    findings['internal'] = internal
    summary = {}
    for dmp in damps:
        key = 'damp_%.1f' % dmp
        vals = [internal[k]['results'][key] for k in internal if 'rmse' in internal[k]['results'][key]]
        if len(vals) == len(internal):
            summary[key] = {'mean_rmse': float(np.mean([v['rmse'] for v in vals])), 'mean_bias': float(np.mean([v['bias'] for v in vals])), 'mean_mae': float(np.mean([v['mae'] for v in vals]))}
    findings['internal_summary'] = summary
    if summary:
        sel_key = min(summary, key=lambda k: (summary[k]['mean_rmse'], k))
        sel = float(sel_key.split('_')[1])
    else:
        sel_key, sel = 'damp_0.0_default', 0.0
        findings['selection_note'] = 'no complete internal comparison; default damp 0'
    findings['selected'] = sel_key
    b_full, npairs = _growth_rate(day, y)
    findings['full_yoy_pairs'] = int(npairs)
    findings['full_b_per_day'] = b_full
    if b_full is None:
        b_full = 0.0
        findings['fallback_used'] = True
        findings['fallback_reason'] = 'no_growth_estimate_full'
    ref = float(ud[-1])
    findings['implied_factor_at_eval_mid'] = float(np.exp(sel * b_full * (float(np.median(Xe[:, ed])) - ref)))
    findings['implied_annual_factor_undamped'] = float(np.exp(b_full * 365.0))
    try:
        pred, nit = _fit_predict(X, y, Xe, ed, sel * b_full, ref)
        findings['final_n_iter'] = nit
        findings['submitted'] = 'poisson_trend_normalized_' + sel_key
    except Exception as exc:
        findings['fallback_used'] = True
        findings['fallback_reason'] = type(exc).__name__
        findings['submitted'] = 'poisson_plain_fallback'
        m = _model()
        m.fit(X, y)
        pred = np.clip(m.predict(Xe), 0.0, None)
    pred = np.asarray(pred, dtype=float)
    bad = ~np.isfinite(pred)
    if bad.any():
        findings['fallback_used'] = True
        findings['nonfinite_replaced'] = int(bad.sum())
        pred[bad] = float(np.median(y))
    findings['pred_mean'] = float(pred.mean())
    findings['train_last60_mean'] = float(y[day >= ud[-1] - 59].mean())
    findings['eval_day_range'] = [float(Xe[:, ed].min()), float(Xe[:, ed].max())]
    return {'prediction': pred.tolist(), 'findings': findings}

import numpy as np
from sklearn.ensemble import HistGradientBoostingRegressor

def _model():
    return HistGradientBoostingRegressor(loss='poisson', max_iter=250, learning_rate=0.08, max_leaf_nodes=31, l2_regularization=1, random_state=1729)

def _metrics(p, y):
    e = p - y
    return {'rmse': float(np.sqrt(np.mean(e ** 2))), 'mae': float(np.mean(np.abs(e))), 'bias': float(np.mean(e)), 'pred_mean': float(np.mean(p))}

def _weights(day, hl):
    if hl is None:
        return np.ones_like(day, dtype=float)
    w = np.power(0.5, (float(day.max()) - day) / float(hl))
    return w / w.mean()

def _ess(w):
    return float(w.sum() ** 2 / np.sum(w ** 2))

def _fit_predict(Xtr, ytr, Xte, day_tr, hl):
    m = _model()
    m.fit(Xtr, ytr, sample_weight=_weights(day_tr, hl))
    return np.clip(m.predict(Xte), 0.0, None), int(m.n_iter_)

def fit_predict(train, inputs, seed):
    X = np.asarray(train['X'], dtype=float)
    y = np.asarray(train['y'], dtype=float)
    Xe = np.asarray(inputs['X'], dtype=float)
    names = list(train['feature_names'])
    ed = names.index('elapsed_day')
    day = X[:, ed]
    ud = np.unique(day)
    cands = [('hl_none', None), ('hl_365', 365.0), ('hl_180', 180.0), ('hl_90', 90.0)]
    order = {k: i for i, (k, _) in enumerate(cands)}
    findings = {'fallback_used': False, 'design': 'poisson HGB (idea-a0bc19 hparams, all features) with exponential recency sample weights w=0.5**((last_fit_day-day)/half_life), normalized to mean 1; half-life selected by mean RMSE over 3 chronological folds with 61-day horizon, ties toward hl_none; only sample weights vary', 'horizon_days': 61, 'candidates': [k for k, _ in cands]}
    internal = {}
    for lo in [ud[-91], ud[-61], ud[-31]]:
        hi = lo + 61.0
        tr = day < lo
        ho = (day >= lo) & (day < hi)
        fold = {'train_rows': int(tr.sum()), 'holdout_rows': int(ho.sum()), 'holdout_mean_y': float(y[ho].mean()), 'results': {}}
        for key, hl in cands:
            try:
                p, nit = _fit_predict(X[tr], y[tr], X[ho], day[tr], hl)
                r = _metrics(p, y[ho])
                r['n_iter'] = nit
                r['ess'] = _ess(_weights(day[tr], hl))
            except Exception as exc:
                r = {'error': type(exc).__name__}
            fold['results'][key] = r
        internal['cut_%d' % int(lo)] = fold
    findings['internal'] = internal
    summary = {}
    for key, hl in cands:
        vals = [internal[k]['results'][key] for k in internal if 'rmse' in internal[k]['results'][key]]
        if len(vals) == len(internal):
            summary[key] = {'mean_rmse': float(np.mean([v['rmse'] for v in vals])), 'mean_bias': float(np.mean([v['bias'] for v in vals])), 'mean_mae': float(np.mean([v['mae'] for v in vals]))}
    findings['internal_summary'] = summary
    if summary:
        sel_key = min(summary, key=lambda k: (summary[k]['mean_rmse'], order[k]))
    else:
        sel_key = 'hl_none'
        findings['selection_note'] = 'no complete internal comparison; default hl_none'
    sel_hl = dict(cands)[sel_key]
    findings['selected'] = sel_key
    findings['selected_half_life_days'] = sel_hl
    try:
        pred, nit = _fit_predict(X, y, Xe, day, sel_hl)
        findings['final_n_iter'] = nit
        findings['final_ess'] = _ess(_weights(day, sel_hl))
        findings['submitted'] = 'poisson_recency_' + sel_key
    except Exception as exc:
        findings['fallback_used'] = True
        findings['fallback_reason'] = type(exc).__name__
        findings['submitted'] = 'poisson_uniform_fallback'
        m = _model()
        m.fit(X, y)
        pred = np.clip(m.predict(Xe), 0.0, None)
    pred = np.asarray(pred, dtype=float)
    bad = ~np.isfinite(pred)
